function performanceRating(p){const s=p.stats;if(p.keeper){const saveRate=s.faced?s.saves/s.faced:.7;return clamp(6+(saveRate-.65)*1.8+s.saves*.12-s.conceded*.35+s.cleanSheet*.55+(s.passes?s.passComplete/s.passes-.65:0)*.5,3.5,9.5)}const passRate=s.passes?s.passComplete/s.passes:.7,duelRate=s.duels?s.duelsWon/s.duels:.5;let rating=6+(passRate-.7)*1.2+(duelRate-.5)*1.1+s.progressive*.035+s.interceptions*.16+s.onTarget*.12+s.goals*1.15+s.assists*.55-s.passLost*.05;const line=p.assignedLine||p.line;if(line==='def')rating+=s.cleanSheet*.35+s.interceptions*.08;if(line==='att')rating+=s.goals*.25+s.onTarget*.08;return clamp(rating,3.5,9.5)}
function updateForm(source,rating){source.history=[...(source.history||[]),rating].slice(-5);const weighted=source.history.reduce((s,v,i)=>s+v*(i+1),0),weights=source.history.reduce((s,_,i)=>s+i+1,0),average=weighted/weights;source.form=average<5.35?-2:average<5.9?-1:average<6.75?0:average<7.45?1:2}
function performanceText(v){return v<5.25?'enttäuschend':v<5.85?'schwach':v<6.55?'ordentlich':v<7.25?'gut':v<8.2?'sehr gut':'herausragend'}
function finishMatch(){const m=match;m.finished=true;running=false;m.flight=null;hideOverlay();m.people.forEach(p=>{p.stats.cleanSheet=m.score[1-p.t]===0?1:0;p.stats.rating=performanceRating(p)});m.people.filter(p=>p.t===0).forEach(person=>{const source=person.keeper?homeKeeper:players.find(p=>p.name===person.name);if(!source)return;const workload=typeof v51Workload==='function'?v51Workload(person,Boolean(press)):person.keeper?9:20+(100-(person.sta||70))*.12+(press?6:0)+(person.age>=33?3:0);updateForm(source,person.stats.rating);source.fresh=clamp(source.fresh-workload,0,100)});$('#board-label').textContent='ABPFIFF';$('#back').hidden=false;const[h,a]=m.score;$('#match-title').textContent=h>a?'Sieg für FC Viertel!':h<a?'SC Hafen gewinnt.':'Unentschieden.';note(`Abpfiff! FC Viertel ${h} : ${a} SC Hafen.`,'major');renderMatchReport()}
function renderMatchReport(){const panel=$('#player-stats'),people=match.people.filter(p=>p.t===0);panel.innerHTML=`<h3>Spielerstatistik</h3><div class="stat-row stat-head"><span>Spieler</span><span>Leistung</span><span>Werte</span></div>${people.map(p=>{const s=p.stats,details=p.keeper?`${s.saves} Paraden · ${s.cleanSheet?'zu null':s.conceded+' GT'}`:`${s.passComplete}/${s.passes} Pässe · ${s.goals} Tore · ${s.assists} Vorlagen · ${s.duelsWon}/${s.duels} ZK`;return `<div class="stat-row"><b>${p.name}</b><span>${performanceText(s.rating)}</span><span>${details}</span></div>`}).join('')}`;panel.hidden=false}
function teamShortCode(name){const words=String(name||'').trim().split(/\s+/).filter(word=>/\p{L}/u.test(word));return(words.length>1?words.slice(0,2).map(word=>word[0]).join(''):words[0]?.slice(0,3)||'TEAM').toUpperCase()}
function updateTeamStats(){const m=match;$('#score').textContent=m.score.join(' : ');$('#clock').textContent=String(displayMatchMinute(m.elapsed)).padStart(2,'0')+'′';const possession=m.possession[0]+m.possession[1]?Math.round(m.possession[0]/(m.possession[0]+m.possession[1])*100):50,homeName=typeof activeSave!=='undefined'&&activeSave?.club||'FC Viertel',awayName=m.opponentName||m.cupOpponentName||(typeof activeSave!=='undefined'&&activeSave&&typeof activeOpponent==='function'?activeOpponent().name:'SC Hafen');for(const label of document.querySelectorAll('[data-stat-home]'))label.textContent=homeName;for(const label of document.querySelectorAll('[data-stat-away]'))label.textContent=awayName;const passes=[{total:0,complete:0},{total:0,complete:0}];for(const player of m.people){passes[player.t].total+=player.stats.passes;passes[player.t].complete+=player.stats.passComplete}for(const[id,values]of[['#shots',m.shots.map(String)],['#possession',[`${possession} %`,`${100-possession} %`]],['#pass-rate',passes.map(team=>team.total?`${Math.round(team.complete/team.total*100)} %`:'–')]]){const root=$(id);if(!root)continue;root.querySelector('[data-stat-value="home"]').textContent=values[0];root.querySelector('[data-stat-value="away"]').textContent=values[1]}}

function draw(){const c=$('#canvas'),ctx=c.getContext('2d'),w=600,h=740;ctx.clearRect(0,0,w,h);for(let i=0;i<10;i++){ctx.fillStyle=i%2?'#245446':'#214e43';ctx.fillRect(0,i*h/10,w,h/10)}ctx.strokeStyle='#b5d7ba88';ctx.lineWidth=2;ctx.strokeRect(28,26,w-56,h-52);ctx.beginPath();ctx.moveTo(28,h/2);ctx.lineTo(w-28,h/2);ctx.stroke();ctx.beginPath();ctx.arc(w/2,h/2,70,0,Math.PI*2);ctx.stroke();ctx.strokeRect(w*.25,26,w*.5,105);ctx.strokeRect(w*.25,h-131,w*.5,105);ctx.strokeRect(w*.4,10,w*.2,16);ctx.strokeRect(w*.4,h-26,w*.2,16);for(const p of match.people){const x=p.x*w,y=p.y*h;if(p===match.owner){ctx.strokeStyle='#fff8';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y,23+Math.sin(match.elapsed*6)*2,0,Math.PI*2);ctx.stroke()}ctx.fillStyle='#0003';ctx.beginPath();ctx.ellipse(x,y+9,19,13,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=p.keeper?'#e5b56a':p.t===0?'#c7f36b':'#7bb7e9';ctx.strokeStyle=p.t===0?'#e5ffb0':'#bedfff';ctx.beginPath();ctx.arc(x,y,17,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#142629';ctx.font='bold 16px Arial';ctx.textAlign='center';ctx.fillText(p.n,x,y+6);ctx.fillStyle='#edf7ee';ctx.font='12px Arial';ctx.fillText(p.name,x,y+33)}const b=match.ball;ctx.fillStyle='#0005';ctx.beginPath();ctx.arc(b.x*w+2,b.y*h+3,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.strokeStyle='#17292b';ctx.beginPath();ctx.arc(b.x*w,b.y*h,6,0,Math.PI*2);ctx.fill();ctx.stroke()}
